.walkin-card{max-width:800px}.walkin-card form{display:grid;grid-template-columns:1fr 1fr;gap:16px}.walkin-card label{display:grid;gap:7px;font-size:12px;font-weight:700;color:var(--muted)}.walkin-card input,.walkin-card select{border:1px solid var(--line);border-radius:7px;padding:11px;background:#fff;font:inherit;color:var(--ink)}.walkin-card .full{grid-column:1/-1}.walkin-submit{border:0;border-radius:7px;background:var(--orange);color:#fff;padding:13px 18px;font:700 14px 'DM Sans';cursor:pointer}.walkin-note{color:var(--muted);font-size:12px;margin:0}.walkin-date-fields{display:grid;grid-template-columns:1fr 1fr;gap:16px}.walkin-date-fields input[readonly]{cursor:pointer}.walkin-calendar{border:1px solid var(--line);border-radius:8px;padding:15px;background:#fff}.walkin-calendar[aria-disabled="true"]{opacity:.55}.walkin-calendar-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin-bottom:14px}.walkin-calendar-heading strong{display:block}.walkin-calendar-heading small{display:block;color:var(--muted);font-size:11px;margin-top:3px}.walkin-calendar-controls{display:flex;gap:7px;align-items:center}.walkin-calendar-controls b{min-width:118px;text-align:center;font-size:12px}.walkin-calendar-controls button{width:28px;height:28px;border:1px solid var(--line);border-radius:5px;background:#fff;color:var(--orange-dark);font-size:18px;cursor:pointer}.walkin-weekdays,.walkin-days{display:grid;grid-template-columns:repeat(7,1fr);column-gap:0;row-gap:5px}.walkin-weekdays{margin-bottom:6px}.walkin-weekdays span{text-align:center;color:var(--muted);font-size:10px;font-weight:700}.walkin-day,.walkin-blank{aspect-ratio:1;border:0;background:transparent;display:grid;place-items:center;font:600 12px 'DM Sans';color:var(--ink)}.walkin-day{cursor:pointer;border-radius:0}.walkin-day:hover:not([disabled]){background:#fff0d8}.walkin-day.booked{background:#f8dcd9;color:#8f332d;cursor:not-allowed}.walkin-day.booked-start,.walkin-day.booked-end{background:#c63e36;color:#fff}.walkin-day.booked-start{border-radius:5px 0 0 5px}.walkin-day.booked-end{border-radius:0 5px 5px 0}.walkin-day.booked-start.booked-end{border-radius:5px}.walkin-day.past{color:#c8c0b8;cursor:not-allowed}.walkin-day.selected{background:var(--orange);color:#fff}.walkin-day.selected.start{border-radius:5px 0 0 5px}.walkin-day.selected.end{border-radius:0 5px 5px 0}.walkin-day.selected.range{background:#ffe1a5;color:#875000}.walkin-calendar-note{margin:12px 0 0;color:var(--orange-dark);font-size:11px}@media(max-width:700px){.walkin-card form,.walkin-date-fields{grid-template-columns:1fr}.walkin-calendar-heading{display:block}.walkin-calendar-controls{margin-top:10px;justify-content:space-between}.walkin-calendar-controls b{min-width:auto}}
</style><style>.walkin-calendar{max-width:620px}.walkin-day,.walkin-blank{font-size:14px}.walkin-weekdays span{font-size:11px}@media(max-width:700px){.walkin-calendar{max-width:none}.walkin-day,.walkin-blank{font-size:13px}}</style></head>
