<section class="walkin-calendar full" id="walkin-calendar" aria-disabled="true"><div class="walkin-calendar-heading"><div><strong>Room availability</strong><small>Choose a room to view unavailable dates in red.</small></div><div class="walkin-calendar-controls"><button type="button" id="walkin-previous" aria-label="Previous month">‹</button><b id="walkin-month"></b><button type="button" id="walkin-next" aria-label="Next month">›</button></div></div><div class="walkin-weekdays"><span>Sun</span><span>Mon</span><span>Tue</span><span>Wed</span><span>Thu</span><span>Fri</span><span>Sat</span></div><div class="walkin-days" id="walkin-days"></div><p class="walkin-calendar-note" id="walkin-note">Choose a room to load availability.</p></section>
<label class="full">Payment method<select name="payment_method"><option value="gcash">GCash</option><option value="cash">Pay at property</option></select></label><p class="walkin-note full">This creates a confirmed booking immediately and marks the room occupied for the selected dates.</p><button class="walkin-submit full">Confirm walk-in booking</button></form></section></main></div>
<script>
document.addEventListener('DOMContentLoaded',()=>{const room=document.getElementById('walkin-room'),calendar=document.getElementById('walkin-calendar'),days=document.getElementById('walkin-days'),month=document.getElementById('walkin-month'),note=document.getElementById('walkin-note'),checkIn=document.getElementById('walkin-check-in'),checkOut=document.getElementById('walkin-check-out'),inDisplay=document.getElementById('walkin-check-in-display'),outDisplay=document.getElementById('walkin-check-out-display');const today=new Date();today.setHours(0,0,0,0);let cursor=new Date(today.getFullYear(),today.getMonth(),1),ranges=[];const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,pretty=v=>v?new Date(`${v}T00:00:00`).toLocaleDateString('en-PH',{month:'short',day:'numeric',year:'numeric'}):'',occupied=v=>ranges.some(r=>v>=r.start&&v<r.end),overlap=(s,e)=>ranges.some(r=>s<r.end&&e>r.start),sync=()=>{inDisplay.value=pretty(checkIn.value);outDisplay.value=pretty(checkOut.value)};const render=()=>{days.innerHTML='';month.textContent=cursor.toLocaleDateString('en-PH',{month:'long',year:'numeric'});const first=new Date(cursor.getFullYear(),cursor.getMonth(),1),last=new Date(cursor.getFullYear(),cursor.getMonth()+1,0);for(let i=0;i<first.getDay();i++)days.insertAdjacentHTML('beforeend','<span class="walkin-blank"></span>');for(let n=1;n<=last.getDate();n++){const date=new Date(cursor.getFullYear(),cursor.getMonth(),n),v=iso(date),booked=occupied(v),past=date<today,prev=new Date(date),next=new Date(date);prev.setDate(prev.getDate()-1);next.setDate(next.getDate()+1);const bookClass=booked?` booked${occupied(iso(prev))?'':' booked-start'}${occupied(iso(next))?'':' booked-end'}`:'',selected=v===checkIn.value?' selected start':v===checkOut.value?' selected end':checkIn.value&&checkOut.value&&v>checkIn.value&&v<checkOut.value?' selected range':'';days.insertAdjacentHTML('beforeend',`<button type="button" class="walkin-day${booked?bookClass:past?' past':''}${selected}" data-date="${v}" ${(booked||past||!room.value)?'disabled':''}>${n}</button>`)}document.querySelectorAll('.walkin-day:not([disabled])').forEach(b=>b.addEventListener('click',()=>choose(b.dataset.date)))};const choose=v=>{if(!checkIn.value||checkOut.value){checkIn.value=v;checkOut.value='';note.textContent='Check-in selected. Now choose check-out.'}else if(v<=checkIn.value){checkIn.value=v;checkOut.value='';note.textContent='Check-in updated. Now choose check-out.'}else if(overlap(checkIn.value,v)){note.textContent='Those dates include an existing reservation. Choose dates outside the red range.';return}else{checkOut.value=v;note.textContent='The selected dates are available.'}sync();render()};const load=async()=>{const url=room.selectedOptions[0]?.dataset.availabilityUrl;if(!url){ranges=[];calendar.setAttribute('aria-disabled','true');note.textContent='Choose a room to load availability.';render();return}try{const res=await fetch(url,{headers:{Accept:'application/json'},cache:'no-store'});if(!res.ok)return;const data=await res.json();ranges=data.ranges;calendar.setAttribute('aria-disabled','false');if(checkIn.value&&checkOut.value&&overlap(checkIn.value,checkOut.value)){checkOut.value='';sync();note.textContent='Availability changed. Choose a new check-out date.'}else note.textContent='Unavailable dates are shown in red.';render()}catch(error){note.textContent='Could not load room availability. Please try again.'}};room.addEventListener('change',load);document.getElementById('walkin-previous').addEventListener('click',()=>{const prev=new Date(cursor.getFullYear(),cursor.getMonth()-1,1);if(prev>=new Date(today.getFullYear(),today.getMonth(),1)){cursor=prev;render()}});document.getElementById('walkin-next').addEventListener('click',()=>{cursor=new Date(cursor.getFullYear(),cursor.getMonth()+1,1);render()});inDisplay.addEventListener('click',()=>calendar.scrollIntoView({behavior:'smooth',block:'center'}));outDisplay.addEventListener('click',()=>calendar.scrollIntoView({behavior:'smooth',block:'center'}));setInterval(load,30000);sync();render();if(room.value)load()});
</script></body></html>
